#include <stdio.h>
#include <string.h>
void reverse(char* str) {
    int l = 0, r = strlen(str) - 1;
    while (l < r) {
        char t = str[l]; str[l++] = str[r]; str[r--] = t;
    }
}
int main() {
    char s[] = "SolveAI";
    reverse(s);
    printf("Reversed: %s\n", s);
    return 0;
}

